#include <iostream>
#include <vector>
#include <deque>
#include <cstring>
#include <climits>
#include <algorithm>
using namespace std;

char gridA[12][12], gridB[12][12];
int sizeN, maxTime;
bool visited[70][12][12][12][12];
bool reachable[12][12][12][12];
int timeToReach[12][12];
vector<vector<int>> graph;
int capacity[210][210], flow[210][210];
int nodeExcess[210], nodeHeight[210];
int nodeIndex[11][11];

void dfs(int step, int x, int y, int startX, int startY) {
    if (maxTime >= 70) return;
    if (x < 0 || x >= sizeN || y < 0 || y >= sizeN) return;
    if (gridA[x][y] < '0' || gridA[x][y] > '9') return;
    if (step > maxTime + 1) return;
    if (visited[step][x][y][startX][startY]) return;
    if (step > timeToReach[x][y] && timeToReach[x][y] != 0) return;
    if (step == timeToReach[x][y] && timeToReach[x][y] != 0 && (gridB[x][y] > '9' || gridB[x][y] <= '0')) return;
    visited[step][x][y][startX][startY] = true;
    if (step < timeToReach[x][y]) {
        dfs(step+1, x, y, startX, startY);
        dfs(step+1, x+1, y, startX, startY);
        dfs(step+1, x-1, y, startX, startY);
        dfs(step+1, x, y+1, startX, startY);
        dfs(step+1, x, y-1, startX, startY);
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("1.txt", "rt", stdin);
#endif
    cin >> sizeN >> maxTime;
    for (int i = 0; i < sizeN; ++i)
        for (int j = 0; j < sizeN; ++j)
            cin >> gridA[i][j];
    for (int i = 0; i < sizeN; ++i)
        for (int j = 0; j < sizeN; ++j)
            cin >> gridB[i][j];

    deque<pair<int,int>> queue;
    memset(timeToReach, -1, sizeof(timeToReach));
    for (int i = 0; i < sizeN; ++i)
        for (int j = 0; j < sizeN; ++j)
            if (gridA[i][j] == 'Z') {
                timeToReach[i][j] = 0;
                queue.emplace_back(i, j);
            }

    const int dx[4] = {-1, 0, 1, 0};
    const int dy[4] = {0, -1, 0, 1};
    while (!queue.empty()) {
        auto [x, y] = queue.front(); queue.pop_front();
        if (timeToReach[x][y] >= maxTime) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < sizeN && ny >= 0 && ny < sizeN &&
                gridA[nx][ny] >= '0' && gridA[nx][ny] <= '9' && timeToReach[nx][ny] == -1) {
                timeToReach[nx][ny] = timeToReach[x][y] + 1;
                queue.emplace_back(nx, ny);
            }
        }
    }
    for (int i = 0; i < sizeN; ++i)
        for (int j = 0; j < sizeN; ++j)
            if (timeToReach[i][j] == -1) timeToReach[i][j] = maxTime;

    for (int i = 0; i < sizeN; ++i)
        for (int j = 0; j < sizeN; ++j)
            if (gridA[i][j] >= '0' && gridA[i][j] <= '9')
                dfs(0, i, j, i, j);

    for (int i1 = 0; i1 < sizeN; ++i1)
        for (int j1 = 0; j1 < sizeN; ++j1)
            for (int i2 = 0; i2 < sizeN; ++i2)
                for (int j2 = 0; j2 < sizeN; ++j2)
                    for (int step = 0; step <= maxTime; ++step)
                        reachable[i1][j1][i2][j2] |= visited[step][i1][j1][i2][j2];

    graph.resize(1);
    for (int i1 = 0; i1 < sizeN; ++i1)
        for (int j1 = 0; j1 < sizeN; ++j1)
            if (gridA[i1][j1] > '0' && gridA[i1][j1] <= '9') {
                int u = graph.size();
                graph.emplace_back();
                nodeExcess[u] = gridA[i1][j1] - '0';
                for (int i2 = 0; i2 < sizeN; ++i2)
                    for (int j2 = 0; j2 < sizeN; ++j2)
                        if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && reachable[i2][j2][i1][j1]) {
                            int v;
                            if (nodeIndex[i2][j2] == 0) {
                                nodeIndex[i2][j2] = graph.size();
                                graph.emplace_back();
                            }
                            v = nodeIndex[i2][j2];
                            graph[u].push_back(v);
                            graph[v].push_back(u);
                            capacity[u][v] = 10000;
                            capacity[v][u] = 0;
                        }
            }

    for (int i2 = 0; i2 < sizeN; ++i2)
        for (int j2 = 0; j2 < sizeN; ++j2)
            if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && nodeIndex[i2][j2] > 0) {
                int v = nodeIndex[i2][j2];
                graph[v].push_back(0);
                capacity[v][0] = gridB[i2][j2] - '0';
                capacity[0][v] = 0;
            }

    for (int i = 0; i < (int)graph.size(); ++i) nodeHeight[i] = 0;
    nodeHeight[0] = graph.size();

    while (true) {
        bool updated = false;
        for (int u = 1; u < (int)graph.size(); ++u) {
            while (nodeExcess[u] > 0) {
                bool pushed = false;
                int minHeight = INT_MAX;
                for (int v : graph[u]) {
                    if (capacity[u][v] - flow[u][v] > 0) minHeight = min(minHeight, nodeHeight[v]);
                    if (capacity[u][v] - flow[u][v] > 0 && nodeHeight[u] == nodeHeight[v] + 1) {
                        int delta = min(capacity[u][v] - flow[u][v], nodeExcess[u]);
                        flow[u][v] += delta;
                        flow[v][u] -= delta;
                        nodeExcess[u] -= delta;
                        nodeExcess[v] += delta;
                        pushed = true;
                        updated = true;
                        if (nodeExcess[u] == 0) goto nextNode;
                    }
                }
                if (nodeHeight[u] != minHeight + 1 && minHeight != INT_MAX) {
                    nodeHeight[u] = minHeight + 1;
                    updated = true;
                }
                if (!pushed) nextNode: break;
            }
        }
        if (!updated) break;
    }

    cout << nodeExcess[0];
    return 0;
}
